import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Verify resource trends for an optional desktop client","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/desktop-soak","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/desktop-soak.md","filePath":"en/tutorials/desktop-soak.md"}'),i={name:"en/tutorials/desktop-soak.md"};function r(n,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="verify-resource-trends-for-an-optional-desktop-client" tabindex="-1">Verify resource trends for an optional desktop client <a class="header-anchor" href="#verify-resource-trends-for-an-optional-desktop-client" aria-label="Permalink to &quot;Verify resource trends for an optional desktop client&quot;">​</a></h1><p>Desktop Soak is needed when you provide an Electron client. Backend documentation, HTTP contracts and the static documentation site do not depend on it. This guide observes RSS, JS heap, DOM nodes and listeners while a real shell repeatedly uses shared pages. Growth is report evidence; one soak cannot establish a leak.</p><p>Prerequisites are an <a href="./electron-shell">Electron shell</a> loading your Web pages, verified backend contracts, Docker, pnpm and a display or xvfb. Run commands from the repository root.</p><h2 id="verify-collection-first" tabindex="-1">Verify collection first <a class="header-anchor" href="#verify-collection-first" aria-label="Permalink to &quot;Verify collection first&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DESKTOP_SOAK_DURATION_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">25</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-desktop-soak</span></span></code></pre></div><p>The current <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/perf/desktop-soak.mjs" target="_blank" rel="noreferrer">runner</a> creates isolated PostgreSQL/Redis/RustFS/Mailpit, API/Web and a temporary user directory. It seeds knowledge data through HTTP and launches real Electron. It removes its own containers, volumes and user directory afterward without using development data.</p><p>Success writes <code>.scratch/perf/desktop-soak-report.json</code> with raw series, aggregates, growth observations, git SHA, desktop/Electron versions and sampling configuration. A short run establishes wiring and collection, not long-term stability.</p><h2 id="adapt-the-cycle-to-your-pages" tabindex="-1">Adapt the cycle to your pages <a class="header-anchor" href="#adapt-the-cycle-to-your-pages" aria-label="Permalink to &quot;Adapt the cycle to your pages&quot;">​</a></h2><p>The current <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/tests/desktop/soak.spec.ts" target="_blank" rel="noreferrer">collection scenario</a> runs list, detail, attachment refresh/download/upload, deletion of the new attachment, opening/canceling a dialog, sampling and return to the list. For your business:</p><ol><li>Seed fixed-size data through public APIs, then sign in and navigate through real pages.</li><li>Pick the heaviest repeatable screen for sampling, such as details after file and task panels load.</li><li>Clean up each cycle&#39;s additions so dataset growth cannot masquerade as resource growth.</li><li>Preserve real downloads, requests and component lifecycles; adapt selectors and business actions.</li><li>Register scenario/collector ownership so removing a business does not leave invalid entries.</li></ol><h2 id="measurement-boundaries" tabindex="-1">Measurement boundaries <a class="header-anchor" href="#measurement-boundaries" aria-label="Permalink to &quot;Measurement boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Source</th><th>Limit</th></tr></thead><tbody><tr><td><code>rendererRssKiB</code></td><td>Renderer working set from main-process <code>app.getAppMetrics()</code></td><td>Includes Chromium and allocator behavior; growth is not necessarily a JS leak</td></tr><tr><td><code>heapKiB</code></td><td><code>performance.memory.usedJSHeapSize</code></td><td>GC causes fluctuations; unavailable values are null</td></tr><tr><td><code>domNodes</code></td><td>Current document&#39;s element count</td><td>Samples need comparable page state</td></tr><tr><td><code>listeners</code></td><td>Net EventTarget registrations through a wrapper</td><td>Long-lived targets only, such as window/document/body/root; not a complete listener inventory</td></tr></tbody></table><p>The counter deduplicates target, event type, capture phase and listener, and accounts for <code>once</code> and AbortSignal removal. The initialization script measures the client without changing production business code.</p><h2 id="run-longer-repeat-and-diagnose" tabindex="-1">Run longer, repeat and diagnose <a class="header-anchor" href="#run-longer-repeat-and-diagnose" aria-label="Permalink to &quot;Run longer, repeat and diagnose&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DESKTOP_SOAK_DURATION_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3600</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-desktop-soak</span></span></code></pre></div><p>Defaults are a 300-second cycle, <code>DESKTOP_SOAK_WARMUP_SECS=15</code> and <code>DESKTOP_SOAK_SAMPLE_MS=2000</code>. <code>PERF_SCALE</code> controls current reference data size. Warmup lets initial hydration and lazy loading finish before steady sampling.</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/perf/desktop-report.mjs" target="_blank" rel="noreferrer">Report shaping</a> compares first/last-quartile medians. Growth above 25% produces <code>growthNotes</code> without changing exit status. Repeat with the same revision and scale to distinguish in-run allocation, GC and accumulation across runs; keep raw points and environment metadata. Startup or page assertion failures still fail the command and must be fixed before interpreting a curve.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/desktop-soak-report.test.mjs</span></span></code></pre></div><p>This deterministic report check is part of daily validation. Real GUI smoke and soak belong to client milestones and nightly runs; soak is outside ordinary PR <code>just check</code>. Knowledge removal deletes its current scenario and runner, leaving the original recipe pointing to a removed script. Generic report shaping remains. Rebuild your business runner and collection scenario, then update the recipe before running soak.</p><p>Next: <a href="./add-example">Contribute your pages to the application shell</a>.</p><hr><p>Source version：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/26-desktop-soak.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',22)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
